};


// Helper function for making authenticated API requests
const apiRequest = async (endpoint, method = 'GET', data = null) => {
  const url = `${API_URL}${endpoint}`;
  const token = getAuthToken();

  const headers = {
    'Content-Type': 'application/json',
  };

  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const options = {
    method,
    headers,
  };

  if (data) {
    options.body = JSON.stringify(data);
  }

  try {
    const response = await fetch(url, options);

    // Token expired, try to refresh
    if (response.status === 401) {
      const refreshed = await refreshToken();
      if (refreshed) {
        // Retry the request with new token
        return apiRequest(endpoint, method, data);
      } else {
        // Refresh failed, need to login again
        throw new Error('Authentication expired, please log in again');
      }
    }

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || errorData.error || 'An error occurred');
    }

    // Some endpoints may not return JSON
    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      return await response.json();
    }

    return { success: true };
  } catch (error) {
    console.error(`API Error (${endpoint}):`, error);
    throw error;
  }
};

// File upload helper (for images, audio files)
const uploadFile = async (endpoint, formData) => {
  const url = `${API_URL}${endpoint}`;
